/* Review-only administration. No credentials, real money, or PHI are stored. */
const tenantStates=new Map();let tenantId='tenant-1';let tenants=[{id:'tenant-1',name:'Olamide Medical',status:'Active',plan:'Fleet',currency:'USD'},{id:'tenant-2',name:'Community Transport',status:'Active',plan:'Starter',currency:'USD'}];
let members=[{id:'user-1',name:'Demo operator',role:'Tenant admin',status:'Active'}],products=[{id:'prod-1',name:'Scheduled transport deposit',description:'Demo deposit for scheduled NEMT; final quote requires operator approval.',price:3500,currency:'USD',active:true},{id:'prod-2',name:'Fleet subscription',description:'Monthly software workspace subscription, demonstration only.',price:9900,currency:'USD',active:true}],orders=[],gateways={Stripe:{enabled:false,mode:'Test',reference:''},PayPal:{enabled:false,mode:'Test',reference:''},Paystack:{enabled:false,mode:'Test',reference:''},Flutterwave:{enabled:false,mode:'Test',reference:''}},features={marketplace:true,booking:true},credits=0;
const originalRender=render,originalBooking=booking;
pages['Admin']=['Overview','Marketplace','Users','Fleet','Hospitals','Orders','Payment gateways','Settings','Audit log'];pages['Super admin']=['Overview','Tenants','Users','Marketplace','Orders','Payment gateways','Feature controls','Audit log'];pages.Patient.push('Marketplace','Orders');pages.Dispatcher.push('Marketplace');
const superOption=document.createElement('option');superOption.textContent='Super admin';$('#role').append(superOption);
const picker=document.createElement('select');picker.id='tenant';picker.setAttribute('aria-label','Tenant workspace');$('#role').parentNode.insertBefore(picker,$('#role'));
function currentTenant(){return tenants.find(t=>t.id===tenantId)}
function saveTenantState(){tenantStates.set(tenantId,{vehicles:structuredClone(vehicles),trips:structuredClone(trips),hospitals:structuredClone(hospitals),records:structuredClone(records),audit:structuredClone(audit),profile:structuredClone(profile),settings:structuredClone(settings),members:structuredClone(members),products:structuredClone(products),orders:structuredClone(orders),gateways:structuredClone(gateways),features:structuredClone(features),credits})}
saveTenantState();
function switchTenant(id){if(id===tenantId)return;saveTenantState();tenantId=id;let s=tenantStates.get(id);if(!s){s={vehicles:[],trips:[],hospitals:[],records:[],audit:[],profile:{},settings:{market:'Not configured',model:'Private fleet',video:''},members:[],products:[],orders:[],gateways:structuredClone(gateways),features:{marketplace:true,booking:true},credits:0};Object.values(s.gateways).forEach(g=>{g.enabled=false;g.reference=''})}({vehicles,trips,hospitals,records,audit,profile,settings,members,products,orders,gateways,features,credits}=structuredClone(s));render();toast('Switched to '+currentTenant().name)}
picker.onchange=()=>switchTenant(picker.value);
function adminOnly(){if(!['Admin','Super admin'].includes($('#role').value)){toast('Choose an administrator demo role.');return false}return true}
function tenantWritable(){if(currentTenant().status!=='Active'){toast('This tenant is suspended.');return false}return true}
function money(n,currency='USD'){return new Intl.NumberFormat(undefined,{style:'currency',currency}).format(n/100)}
function wrapper(title,body,action=''){return `<section class="card"><div class="row"><h2>${title}</h2>${action}</div><p class="sub">${esc(currentTenant().name)} · Session-only demonstration · No real payments</p>${body}</section>`}
render=function(){originalRender();picker.innerHTML=tenants.map(t=>`<option value="${t.id}" ${t.id===tenantId?'selected':''}>${esc(t.name)}${t.status==='Suspended'?' · Suspended':''}</option>`).join('');let out;
if(page==='Tenants')out=wrapper('Tenant organizations',`<div class="table-wrap"><table><tr><th>ORGANIZATION</th><th>PLAN</th><th>STATUS</th><th>CONTROLS</th></tr>${tenants.map(t=>`<tr><td>${esc(t.name)}<br><small>${t.id}</small></td><td>${esc(t.plan)}</td><td>${esc(t.status)}</td><td><div class="actions"><button class="btn secondary" onclick="switchTenant('${t.id}')">Open</button><button class="btn secondary" onclick="tenantForm('${t.id}')">Edit</button><button class="btn secondary" onclick="toggleTenant('${t.id}')">${t.status==='Active'?'Suspend':'Activate'}</button></div></td></tr>`).join('')}</table></div>`,`<button class="btn" onclick="tenantForm()">＋ Create tenant</button>`);
if(page==='Users')out=wrapper('Users & roles',`<table><tr><th>NAME</th><th>ROLE</th><th>STATUS</th><th>ACTION</th></tr>${members.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.role)}</td><td>${esc(m.status)}</td><td><button class="btn secondary" onclick="memberForm('${m.id}')">Manage</button></td></tr>`).join('')}</table><p>Role descriptions: Tenant admin manages the organization; Dispatcher coordinates trips; Crew handles assigned journeys; Hospital updates receiving status; Patient requests transport. Super admin is a platform role, not a tenant membership role.</p>`,`<button class="btn" onclick="memberForm()">＋ Add demo member</button>`);
if(page==='Marketplace')out=wrapper('Transport & fleet marketplace',features.marketplace?`<div class="tiles">${products.filter(p=>p.active||['Admin','Super admin'].includes($('#role').value)).map(p=>`<article class="tile"><span class="pill">${p.active?'Published':'Archived'}</span><h2 style="margin-top:15px">${esc(p.name)}</h2><p>${esc(p.description)}</p><h2>${money(p.price,p.currency)}</h2><div class="actions">${p.active?`<button class="btn" onclick="checkout('${p.id}')">Review purchase</button>`:''}${['Admin','Super admin'].includes($('#role').value)?`<button class="btn secondary" onclick="productForm('${p.id}')">Edit</button>`:''}</div></article>`).join('')||'<p class="empty">No products published for this tenant.</p>'}</div>`:'<p>Marketplace disabled for this tenant.</p>',['Admin','Super admin'].includes($('#role').value)?`<button class="btn" onclick="productForm()">＋ Add product</button>`:'');
if(page==='Orders')out=wrapper('Orders & payments',`<table><tr><th>ORDER</th><th>PRODUCT</th><th>AMOUNT</th><th>STATUS</th><th>DETAIL</th></tr>${orders.map(o=>`<tr><td>${o.id}</td><td>${esc(o.product)}</td><td>${money(o.amount,o.currency)}</td><td>${esc(o.status)}</td><td><button class="btn secondary" onclick="orderDetail('${o.id}')">Review</button></td></tr>`).join('')}</table><p class="sub">Demo credit balance: ${money(credits,currentTenant().currency)}. Credits cannot be withdrawn or used as real money.</p>`,['Admin','Super admin'].includes($('#role').value)?`<button class="btn secondary" onclick="creditForm()">Adjust demo credits</button>`:'');
if(page==='Payment gateways')out=wrapper('Payment provider configuration',`<p>Choose providers per tenant. Live checkout is unavailable until a server creates the order, uses server-side credentials, and verifies signed webhooks. Never paste secret keys into this preview.</p><div class="tiles">${Object.entries(gateways).map(([name,g])=>`<div class="tile"><h2>${name}</h2><span class="pill">${g.enabled?'Enabled for simulation':'Disabled'}</span><p>${g.mode} mode · ${g.reference?'Server secret reference specified':'No credential reference'}</p><button class="btn secondary" onclick="gatewayForm('${name}')">Configure</button></div>`).join('')}</div>`);
if(page==='Feature controls')out=wrapper('Tenant feature controls',`<p>Changes affect only the selected tenant in this session.</p>${Object.entries(features).map(([f,on])=>`<div class="queue row"><div><h3>${esc(f)}</h3><span class="sub">${on?'Enabled':'Disabled'}</span></div><button class="btn secondary" onclick="toggleFeature('${f}')">${on?'Disable':'Enable'}</button></div>`).join('')}`);
if(out!==undefined)$('#content').innerHTML=out;
if(currentTenant().status!=='Active')$('#content').insertAdjacentHTML('afterbegin','<div class="notice">TENANT SUSPENDED · Booking and checkout are disabled.</div>');
};
booking=function(){if(!tenantWritable()||!features.booking)return toast('Booking unavailable for this tenant.');originalBooking()};
function tenantForm(id){if($('#role').value!=='Super admin')return;const t=tenants.find(t=>t.id===id)||{};modal(`<h2>${id?'Edit':'Create'} tenant</h2><form onsubmit="saveTenant(event,'${id||''}')"><label>Organization name<input name="name" required maxlength="100" value="${esc(t.name||'')}"></label><label>Plan<select name="plan"><option>Starter</option><option ${t.plan==='Fleet'?'selected':''}>Fleet</option><option ${t.plan==='Enterprise'?'selected':''}>Enterprise</option></select></label><label>Currency<select name="currency">${['USD','NGN','GBP','EUR','GHS','KES','ZAR'].map(c=>`<option ${c===t.currency?'selected':''}>${c}</option>`).join('')}</select></label><button class="btn">Save tenant</button></form>`)}
function saveTenant(e,id){e.preventDefault();if($('#role').value!=='Super admin')return;const data=Object.fromEntries(new FormData(e.target));if(id)Object.assign(tenants.find(t=>t.id===id),data);else tenants.push({...data,id:'tenant-'+(tenants.length+1),status:'Active'});log('Tenant configuration changed');$('#modal').close();render()}
function toggleTenant(id){if($('#role').value!=='Super admin')return;const t=tenants.find(t=>t.id===id);t.status=t.status==='Active'?'Suspended':'Active';log('Tenant '+id+' '+t.status);render()}
function memberForm(id){if(!adminOnly())return;const m=members.find(m=>m.id===id)||{};modal(`<h2>Demo membership</h2><form onsubmit="saveMember(event,'${id||''}')"><label>Display name<input name="name" required maxlength="80" value="${esc(m.name||'')}"></label><label>Tenant role<select name="role">${['Tenant admin','Dispatcher','Crew','Hospital','Patient'].map(r=>`<option ${r===m.role?'selected':''}>${r}</option>`).join('')}</select></label><label>Status<select name="status"><option>Active</option><option ${m.status==='Suspended'?'selected':''}>Suspended</option></select></label><button class="btn">Save demo membership</button></form>`)}
function saveMember(e,id){e.preventDefault();if(!adminOnly())return;const d=Object.fromEntries(new FormData(e.target));if(id)Object.assign(members.find(m=>m.id===id),d);else members.push({...d,id:'user-'+(members.length+1)});log('Membership updated');$('#modal').close();render()}
function productForm(id){if(!adminOnly())return;const p=products.find(p=>p.id===id)||{};modal(`<h2>Marketplace product</h2><form onsubmit="saveProduct(event,'${id||''}')"><label>Name<input name="name" required maxlength="100" value="${esc(p.name||'')}"></label><label>Description<textarea name="description" required maxlength="1000">${esc(p.description||'')}</textarea></label><label>Price in ${esc(currentTenant().currency)}<input name="price" type="number" min="0.01" max="1000000" step="0.01" required value="${p.price?p.price/100:''}"></label><label>Availability<select name="active"><option value="true">Published</option><option value="false" ${p.active===false?'selected':''}>Archived</option></select></label><button class="btn">Save product</button></form>`)}
function saveProduct(e,id){e.preventDefault();if(!adminOnly())return;const d=Object.fromEntries(new FormData(e.target));d.price=Math.round(Number(d.price)*100);if(!Number.isSafeInteger(d.price)||d.price<1)return toast('Invalid price.');d.active=d.active==='true';d.currency=currentTenant().currency;if(id)Object.assign(products.find(p=>p.id===id),d);else products.push({...d,id:'prod-'+(products.length+1)});log('Marketplace product updated');$('#modal').close();render()}
function gatewayForm(name){if(!adminOnly())return;const g=gateways[name];modal(`<h2>${name} settings</h2><p class="sub">Secret references only. No API keys are accepted or transmitted.</p><form onsubmit="saveGateway(event,'${name}')"><label>Simulation status<select name="enabled"><option value="false">Disabled</option><option value="true" ${g.enabled?'selected':''}>Enabled</option></select></label><label>Credential environment variable name<input name="reference" pattern="[A-Z][A-Z0-9_]*" maxlength="80" value="${esc(g.reference)}" placeholder="${name.toUpperCase()}_SECRET_KEY"></label><p>Test mode only in this preview. Provider settings are not a live integration.</p><button class="btn">Save configuration</button></form>`)}
function saveGateway(e,name){e.preventDefault();if(!adminOnly())return;const d=Object.fromEntries(new FormData(e.target));gateways[name]={enabled:d.enabled==='true',mode:'Test',reference:d.reference};log('Gateway settings changed: '+name);$('#modal').close();render()}
function checkout(id){if(!tenantWritable()||!features.marketplace)return toast('Marketplace unavailable.');const p=products.find(p=>p.id===id&&p.active);if(!p)return;const enabled=Object.entries(gateways).filter(([,g])=>g.enabled);modal(`<h2>Review demo purchase</h2><p>${esc(p.name)} · ${money(p.price,p.currency)}</p><p>No card details are collected. No charge will occur. Emergency response never depends on buying this product.</p>${enabled.length?`<form onsubmit="placeOrder(event,'${id}')"><label>Test gateway<select name="gateway">${enabled.map(([name])=>`<option>${name}</option>`).join('')}</select></label><button class="btn">Create simulated order</button></form>`:'<p>No simulation gateway enabled. An admin can enable one under Payment gateways.</p>'}`)}
function placeOrder(e,id){e.preventDefault();if(!tenantWritable()||!features.marketplace)return;const p=products.find(p=>p.id===id&&p.active),name=e.target.gateway.value;if(!p||!gateways[name]?.enabled)return toast('Product or gateway unavailable.');orders.unshift({id:'DEMO-'+(orders.length+1),tenantId,product:p.name,amount:p.price,currency:p.currency,gateway:name,status:'Simulated — unpaid',created:new Date().toISOString()});log('Simulated order created; no charge');$('#modal').close();render();toast('Simulated order created. No payment taken.')}
function orderDetail(id){const o=orders.find(o=>o.id===id);modal(`<h2>${esc(o.id)}</h2><p>${esc(o.product)}<br>${money(o.amount,o.currency)}<br>${esc(o.gateway)}<br>${esc(o.status)}<br>${esc(o.created)}</p><p>No provider payment, refund, payout, or receipt exists. A backend must verify payment independently.</p>${['Admin','Super admin'].includes($('#role').value)&&o.status!=='Cancelled'?`<button class="btn secondary" onclick="cancelOrder('${id}')">Cancel demo order</button>`:''}`)}
function cancelOrder(id){if(!adminOnly())return;orders.find(o=>o.id===id).status='Cancelled';log('Demo order cancelled');$('#modal').close();render()}
function creditForm(){if(!adminOnly())return;modal(`<h2>Adjust demonstration credits</h2><form onsubmit="adjustCredits(event)"><label>Amount in ${esc(currentTenant().currency)} (negative to deduct)<input name="amount" type="number" step="0.01" min="-1000000" max="1000000" required></label><label>Reason<input name="reason" required maxlength="200"></label><button class="btn">Record demo adjustment</button></form>`)}
function adjustCredits(e){e.preventDefault();if(!adminOnly())return;const n=Math.round(Number(e.target.amount.value)*100);if(!Number.isSafeInteger(n)||credits+n<0)return toast('Invalid adjustment or insufficient demo balance.');credits+=n;log('Demo credit adjustment '+money(n,currentTenant().currency)+': '+e.target.reason.value);$('#modal').close();render()}
function toggleFeature(f){if($('#role').value!=='Super admin'||!(f in features))return;features[f]=!features[f];log('Feature '+f+' '+features[f]);render()}
render();
